#!/usr/bin/env node
'use strict';

/**
 * Synthetic corpus for the private slicer 3.9.0 A/B run (spec §8 step 1).
 *
 * Usage: node make-corpus.js <output-dir>
 *
 * Writes only files generated by code (no customer file): binary STLs, core
 * 3MF packages (written by the tiny stored-only ZIP writer below), one
 * AP214 STEP block, and cases.json (the case list ab-client.js reads).
 * Deterministic: the same output bytes on every run, so sha256 of each file
 * is stable across A and B and across machines.
 *
 * Dependency-free: fs, path, crypto only.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------- geometry

/** Box corner i = x + 2y + 4z. Quads listed CCW seen from outside. */
const BOX_QUADS = Object.freeze([
    [0, 2, 3, 1], // bottom  -Z
    [4, 5, 7, 6], // top     +Z
    [0, 1, 5, 4], // front   -Y
    [2, 6, 7, 3], // back    +Y
    [0, 4, 6, 2], // left    -X
    [1, 3, 7, 5]  // right   +X
]);

function boxCorners(x0, y0, z0, x1, y1, z1) {
    const corners = [];
    for (let i = 0; i < 8; i += 1) {
        corners.push([i & 1 ? x1 : x0, i & 2 ? y1 : y0, i & 4 ? z1 : z0]);
    }
    return corners;
}

/** Triangles of a box; `skipFaces` drops quads by index (open-top box). */
function boxTriangles(x0, y0, z0, x1, y1, z1, skipFaces = []) {
    const c = boxCorners(x0, y0, z0, x1, y1, z1);
    const tris = [];
    BOX_QUADS.forEach((q, index) => {
        if (skipFaces.includes(index)) return;
        tris.push([c[q[0]], c[q[1]], c[q[2]]], [c[q[0]], c[q[2]], c[q[3]]]);
    });
    return tris;
}

/**
 * Closed prism of a simple polygon in the XZ plane (listed CCW seen from -Y,
 * i.e. CCW in (x, z)), extruded along Y from 0 to depth. `profileTris` is the
 * profile's triangulation as index triples (CCW in (x, z)).
 */
function prismXZ(profile, profileTris, depth) {
    const tris = [];
    const front = profile.map(([x, z]) => [x, 0, z]);
    const back = profile.map(([x, z]) => [x, depth, z]);
    // Front cap (y = 0): (x, z)-CCW order already gives the -Y normal.
    for (const [a, b, c] of profileTris) tris.push([front[a], front[b], front[c]]);
    // Back cap (y = depth, normal +Y): reversed.
    for (const [a, b, c] of profileTris) tris.push([back[a], back[c], back[b]]);
    // Side walls (outward).
    for (let i = 0; i < profile.length; i += 1) {
        const j = (i + 1) % profile.length;
        tris.push([front[i], back[j], front[j]], [front[i], back[i], back[j]]);
    }
    return tris;
}

function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) { return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; }
function normalOf(t) {
    const n = cross(sub(t[1], t[0]), sub(t[2], t[0]));
    const len = Math.hypot(n[0], n[1], n[2]);
    return len > 0 ? [n[0] / len, n[1] / len, n[2] / len] : [0, 0, 0];
}

/** Signed volume (divergence theorem); positive for an outward-wound closed mesh. */
function signedVolume(tris) {
    let v = 0;
    for (const [a, b, c] of tris) v += a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0]) + a[2] * (b[0] * c[1] - b[1] * c[0]);
    return v / 6;
}

function rotateX(tris, deg) {
    const r = deg * Math.PI / 180;
    const cs = Math.cos(r);
    const sn = Math.sin(r);
    return tris.map((t) => t.map(([x, y, z]) => [x, y * cs - z * sn, y * sn + z * cs]));
}

/** Translate so the bounding box minimum is the origin. */
function ground(tris) {
    const min = [Infinity, Infinity, Infinity];
    for (const t of tris) for (const p of t) for (let k = 0; k < 3; k += 1) min[k] = Math.min(min[k], p[k]);
    return tris.map((t) => t.map((p) => [p[0] - min[0], p[1] - min[1], p[2] - min[2]]));
}

function bbox(tris) {
    const min = [Infinity, Infinity, Infinity];
    const max = [-Infinity, -Infinity, -Infinity];
    for (const t of tris) for (const p of t) for (let k = 0; k < 3; k += 1) {
        min[k] = Math.min(min[k], p[k]);
        max[k] = Math.max(max[k], p[k]);
    }
    return { min, max, size: [max[0] - min[0], max[1] - min[1], max[2] - min[2]] };
}

// ---------------------------------------------------------------- STL

function binaryStl(tris, label) {
    const buffer = Buffer.alloc(84 + tris.length * 50);
    const header = Buffer.from(`r3d synthetic corpus: ${label}`.slice(0, 80), 'ascii');
    header.copy(buffer, 0);
    buffer.writeUInt32LE(tris.length, 80);
    let offset = 84;
    for (const t of tris) {
        const n = normalOf(t);
        for (const value of [...n, ...t[0], ...t[1], ...t[2]]) {
            buffer.writeFloatLE(value, offset);
            offset += 4;
        }
        buffer.writeUInt16LE(0, offset);
        offset += 2;
    }
    return buffer;
}

// ---------------------------------------------------------------- ZIP (stored only)

const CRC_TABLE = (() => {
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n += 1) {
        let c = n;
        for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
        table[n] = c >>> 0;
    }
    return table;
})();

function crc32(buffer) {
    let c = 0xffffffff;
    for (let i = 0; i < buffer.length; i += 1) c = CRC_TABLE[(c ^ buffer[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
}

/** entries: [{name, data: Buffer}] → a ZIP with method 0 (stored), DOS date 1980-01-01. */
function storedZip(entries) {
    const locals = [];
    const centrals = [];
    let offset = 0;
    const DOS_DATE = (0 << 9) | (1 << 5) | 1;
    for (const { name, data } of entries) {
        const nameBytes = Buffer.from(name, 'utf8');
        const crc = crc32(data);
        const local = Buffer.alloc(30);
        local.writeUInt32LE(0x04034b50, 0);
        local.writeUInt16LE(20, 4);
        local.writeUInt16LE(0, 6);
        local.writeUInt16LE(0, 8);
        local.writeUInt16LE(0, 10);
        local.writeUInt16LE(DOS_DATE, 12);
        local.writeUInt32LE(crc, 14);
        local.writeUInt32LE(data.length, 18);
        local.writeUInt32LE(data.length, 22);
        local.writeUInt16LE(nameBytes.length, 26);
        local.writeUInt16LE(0, 28);
        locals.push(local, nameBytes, data);
        const central = Buffer.alloc(46);
        central.writeUInt32LE(0x02014b50, 0);
        central.writeUInt16LE(20, 4);
        central.writeUInt16LE(20, 6);
        central.writeUInt16LE(0, 8);
        central.writeUInt16LE(0, 10);
        central.writeUInt16LE(0, 12);
        central.writeUInt16LE(DOS_DATE, 14);
        central.writeUInt32LE(crc, 16);
        central.writeUInt32LE(data.length, 20);
        central.writeUInt32LE(data.length, 24);
        central.writeUInt16LE(nameBytes.length, 28);
        central.writeUInt16LE(0, 30);
        central.writeUInt16LE(0, 32);
        central.writeUInt16LE(0, 34);
        central.writeUInt16LE(0, 36);
        central.writeUInt32LE(0, 38);
        central.writeUInt32LE(offset, 42);
        centrals.push(central, nameBytes);
        offset += 30 + nameBytes.length + data.length;
    }
    const cd = Buffer.concat(centrals);
    const eocd = Buffer.alloc(22);
    eocd.writeUInt32LE(0x06054b50, 0);
    eocd.writeUInt16LE(0, 4);
    eocd.writeUInt16LE(0, 6);
    eocd.writeUInt16LE(entries.length, 8);
    eocd.writeUInt16LE(entries.length, 10);
    eocd.writeUInt32LE(cd.length, 12);
    eocd.writeUInt32LE(offset, 16);
    eocd.writeUInt16LE(0, 20);
    return Buffer.concat([...locals, cd, eocd]);
}

// ---------------------------------------------------------------- 3MF

const CONTENT_TYPES = '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
    + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
    + '<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>'
    + '</Types>\n';
const RELS = '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    + '<Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/>'
    + '</Relationships>\n';

function fmt(value) {
    // Shortest round-trip decimal; integers stay integers.
    return Number.isInteger(value) ? String(value) : String(value);
}

/** Indexed mesh from triangles (shared vertices, exact coordinate keys). */
function indexMesh(tris) {
    const vertices = [];
    const index = new Map();
    const faces = tris.map((t) => t.map((p) => {
        const key = p.join(',');
        if (!index.has(key)) {
            index.set(key, vertices.length);
            vertices.push(p);
        }
        return index.get(key);
    }));
    return { vertices, faces };
}

function meshXml(tris) {
    const { vertices, faces } = indexMesh(tris);
    return '<mesh><vertices>'
        + vertices.map((p) => `<vertex x="${fmt(p[0])}" y="${fmt(p[1])}" z="${fmt(p[2])}"/>`).join('')
        + '</vertices><triangles>'
        + faces.map((f) => `<triangle v1="${f[0]}" v2="${f[1]}" v3="${f[2]}"/>`).join('')
        + '</triangles></mesh>';
}

function modelXml(resources, build) {
    return '<?xml version="1.0" encoding="UTF-8"?>\n'
        + '<model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">'
        + `<resources>${resources}</resources><build>${build}</build></model>\n`;
}

function threeMf(model) {
    return storedZip([
        { name: '[Content_Types].xml', data: Buffer.from(CONTENT_TYPES, 'utf8') },
        { name: '_rels/.rels', data: Buffer.from(RELS, 'utf8') },
        { name: '3D/3dmodel.model', data: Buffer.from(model, 'utf8') }
    ]);
}

// ---------------------------------------------------------------- STEP (AP214 block)

function stepReal(value) {
    if (Object.is(value, -0)) value = 0;
    const text = Number.isInteger(value) ? `${value}.` : String(value);
    return /[.E]/.test(text) ? text : `${text}.`;
}

/**
 * A minimal, deterministic AP214 (automotive_design) B-rep box:
 * 8 vertices, 12 straight edges, 6 planar faces, one closed shell, mm units.
 */
function stepBlock(a, b, c, name) {
    const lines = [];
    let next = 1;
    const add = (text) => {
        const id = next;
        next += 1;
        lines.push(`#${id}=${text};`);
        return `#${id}`;
    };
    const point = (p) => add(`CARTESIAN_POINT('',(${p.map(stepReal).join(',')}))`);
    const direction = (d) => add(`DIRECTION('',(${d.map(stepReal).join(',')}))`);

    const appContext = add("APPLICATION_CONTEXT('core data for automotive mechanical design processes')");
    add(`APPLICATION_PROTOCOL_DEFINITION('international standard','automotive_design',2000,${appContext})`);
    const productContext = add(`PRODUCT_CONTEXT('',${appContext},'mechanical')`);
    const product = add(`PRODUCT('${name}','${name}','',(${productContext}))`);
    const formation = add(`PRODUCT_DEFINITION_FORMATION('','',${product})`);
    const pdContext = add(`PRODUCT_DEFINITION_CONTEXT('part definition',${appContext},'design')`);
    const definition = add(`PRODUCT_DEFINITION('design','',${formation},${pdContext})`);
    const pdShape = add(`PRODUCT_DEFINITION_SHAPE('','',${definition})`);
    const lengthUnit = add('(LENGTH_UNIT()NAMED_UNIT(*)SI_UNIT(.MILLI.,.METRE.))');
    const angleUnit = add('(NAMED_UNIT(*)PLANE_ANGLE_UNIT()SI_UNIT($,.RADIAN.))');
    const solidUnit = add('(NAMED_UNIT(*)SI_UNIT($,.STERADIAN.)SOLID_ANGLE_UNIT())');
    const uncertainty = add(`UNCERTAINTY_MEASURE_WITH_UNIT(LENGTH_MEASURE(1.E-07),${lengthUnit},'distance_accuracy_value','confusion accuracy')`);
    const geomContext = add(`(GEOMETRIC_REPRESENTATION_CONTEXT(3)GLOBAL_UNCERTAINTY_ASSIGNED_CONTEXT((${uncertainty}))`
        + `GLOBAL_UNIT_ASSIGNED_CONTEXT((${lengthUnit},${angleUnit},${solidUnit}))`
        + "REPRESENTATION_CONTEXT('Context #1','3D Context with UNIT and UNCERTAINTY'))");

    const origin = point([0, 0, 0]);
    const placement = add(`AXIS2_PLACEMENT_3D('',${origin},${direction([0, 0, 1])},${direction([1, 0, 0])})`);

    const corners = boxCorners(0, 0, 0, a, b, c);
    const vertexIds = corners.map((p) => add(`VERTEX_POINT('',${point(p)})`));
    const edges = new Map(); // "i-j" (i<j) -> {id, from}
    const edgeFor = (i, j) => {
        const key = i < j ? `${i}-${j}` : `${j}-${i}`;
        if (!edges.has(key)) {
            const from = Math.min(i, j);
            const to = Math.max(i, j);
            const d = sub(corners[to], corners[from]);
            const length = Math.hypot(d[0], d[1], d[2]);
            const unit = d.map((v) => v / length);
            const vector = add(`VECTOR('',${direction(unit)},${stepReal(length)})`);
            const line = add(`LINE('',${point(corners[from])},${vector})`);
            const id = add(`EDGE_CURVE('',${vertexIds[from]},${vertexIds[to]},${line},.T.)`);
            edges.set(key, { id, from });
        }
        return edges.get(key);
    };
    const faceIds = BOX_QUADS.map((quad) => {
        const oriented = quad.map((from, k) => {
            const to = quad[(k + 1) % 4];
            const edge = edgeFor(from, to);
            return add(`ORIENTED_EDGE('',*,*,${edge.id},${edge.from === from ? '.T.' : '.F.'})`);
        });
        const loop = add(`EDGE_LOOP('',(${oriented.join(',')}))`);
        const bound = add(`FACE_OUTER_BOUND('',${loop},.T.)`);
        const p0 = corners[quad[0]];
        const n = normalOf([p0, corners[quad[1]], corners[quad[2]]]);
        const ref = sub(corners[quad[1]], p0);
        const refLen = Math.hypot(ref[0], ref[1], ref[2]);
        const axis = add(`AXIS2_PLACEMENT_3D('',${point(p0)},${direction(n)},${direction(ref.map((v) => v / refLen))})`);
        const plane = add(`PLANE('',${axis})`);
        return add(`ADVANCED_FACE('',(${bound}),${plane},.T.)`);
    });
    const shell = add(`CLOSED_SHELL('',(${faceIds.join(',')}))`);
    const brep = add(`MANIFOLD_SOLID_BREP('${name}',${shell})`);
    const shapeRep = add(`ADVANCED_BREP_SHAPE_REPRESENTATION('',(${placement},${brep}),${geomContext})`);
    add(`SHAPE_DEFINITION_REPRESENTATION(${pdShape},${shapeRep})`);
    add(`PRODUCT_RELATED_PRODUCT_CATEGORY('part',$,(${product}))`);

    return [
        'ISO-10303-21;',
        'HEADER;',
        `FILE_DESCRIPTION(('${name}'),'2;1');`,
        `FILE_NAME('${name}.step','2026-11-11T00:00:00',(''),(''),'r3d make-corpus','r3d make-corpus','');`,
        "FILE_SCHEMA(('AUTOMOTIVE_DESIGN { 1 0 10303 214 1 1 1 1 }'));",
        'ENDSEC;',
        'DATA;',
        ...lines,
        'ENDSEC;',
        'END-ISO-10303-21;',
        ''
    ].join('\n');
}

// ---------------------------------------------------------------- corpus

function buildFiles() {
    const files = {};
    files['cube-40.stl'] = binaryStl(boxTriangles(0, 0, 0, 40, 40, 40), 'cube 40 mm');
    files['block-9.5x9.5x14.3.stl'] = binaryStl(boxTriangles(0, 0, 0, 9.5, 9.5, 14.3), 'block 9.5 x 9.5 x 14.3 mm');
    files['bar-60x24x8-tilt30x.stl'] = binaryStl(ground(rotateX(boxTriangles(0, 0, 0, 60, 24, 8), 30)),
        'bar 60 x 24 x 8 mm tilted 30 deg about X');
    // Gamma-shaped bracket profile in XZ: a 10 mm post, a 40 mm arm at the top (30 mm overhang).
    const profile = [[0, 0], [10, 0], [10, 25], [40, 25], [40, 30], [0, 30]];
    const profileTris = [[0, 1, 2], [0, 2, 5], [2, 3, 4], [2, 4, 5]];
    files['bracket-overhang.stl'] = binaryStl(prismXZ(profile, profileTris, 10), 'bracket with 30 mm overhang');
    files['bar-230x20x10.stl'] = binaryStl(boxTriangles(0, 0, 0, 230, 20, 10), 'bar 230 x 20 x 10 mm');
    files['bar-300x20x20.stl'] = binaryStl(boxTriangles(0, 0, 0, 300, 20, 20), 'bar 300 x 20 x 20 mm');
    files['cube-0.04-metre-units.stl'] = binaryStl(boxTriangles(0, 0, 0, 0.04, 0.04, 0.04), 'cube 0.04 units (metre export)');
    files['box-open-top-20.stl'] = binaryStl(boxTriangles(0, 0, 0, 20, 20, 20, [1]), 'open-top box 20 mm');
    files['two-shells-10.stl'] = binaryStl([...boxTriangles(0, 0, 0, 10, 10, 10), ...boxTriangles(20, 0, 0, 30, 10, 10)],
        'two separate 10 mm cubes');

    files['cube-40.3mf'] = threeMf(modelXml(
        `<object id="1" type="model">${meshXml(boxTriangles(0, 0, 0, 40, 40, 40))}</object>`,
        '<item objectid="1"/>'
    ));
    const items = [];
    for (let i = 0; i < 8; i += 1) {
        const tx = (i % 4) * 30;
        const ty = Math.floor(i / 4) * 30;
        items.push(`<item objectid="1" transform="1 0 0 0 1 0 0 0 1 ${tx} ${ty} 0"/>`);
    }
    files['cube-20-x8-instances.3mf'] = threeMf(modelXml(
        `<object id="1" type="model">${meshXml(boxTriangles(0, 0, 0, 20, 20, 20))}</object>`,
        items.join('')
    ));
    // Expansion bomb: object 1 is a 12-triangle cube; objects 2..11 each hold
    // 10 components of the level below. Item -> object 11 = 10^10 leaf instances.
    const levels = [`<object id="1" type="model">${meshXml(boxTriangles(0, 0, 0, 1, 1, 1))}</object>`];
    for (let id = 2; id <= 11; id += 1) {
        levels.push(`<object id="${id}" type="model"><components>`
            + `<component objectid="${id - 1}"/>`.repeat(10) + '</components></object>');
    }
    files['expansion-bomb-10x10.3mf'] = threeMf(modelXml(levels.join(''), '<item objectid="11"/>'));

    files['block-20x15x10.step'] = Buffer.from(stepBlock(20, 15, 10, 'r3d_block_20x15x10'), 'ascii');
    return files;
}

const PLA_DEFAULTS = Object.freeze({
    printerProfile: 'P1S', material: 'PLA', layerHeight: '0.2', infill: 20, supports: false,
    orientationMode: 'auto', sizeUnit: 'mm', rotationX: 0, rotationY: 0, rotationZ: 0
});

function caseOf(id, file, overrides = {}, meta = {}) {
    return { id, file, ...PLA_DEFAULTS, ...overrides, ...meta };
}

function buildCases() {
    const cases = [];
    const layerTag = { '0.1': 'l01', '0.2': 'l02', '0.3': 'l03' };
    for (const material of ['PLA', 'PETG', 'ABS', 'TPU']) {
        for (const layerHeight of ['0.1', '0.2', '0.3']) {
            cases.push(caseOf(`cube-p1s-${material.toLowerCase()}-${layerTag[layerHeight]}`, 'cube-40.stl',
                { material, layerHeight }));
        }
    }
    cases.push(caseOf('cube-h2d-pla-l02', 'cube-40.stl', { printerProfile: 'H2D' }));
    for (const [x, y, z] of [[90, 0, 0], [0, 90, 0], [90, 90, 0], [0, 90, 90], [37, 0, 0]]) {
        cases.push(caseOf(`block-preserve-${x}-${y}-${z}`, 'block-9.5x9.5x14.3.stl',
            { orientationMode: 'preserve', rotationX: x, rotationY: y, rotationZ: z }));
    }
    cases.push(caseOf('block-auto', 'block-9.5x9.5x14.3.stl'));
    cases.push(caseOf('tiltbar-auto', 'bar-60x24x8-tilt30x.stl'));
    cases.push(caseOf('tiltbar-preserve-0-0-0', 'bar-60x24x8-tilt30x.stl', { orientationMode: 'preserve' }));
    cases.push(caseOf('bracket-auto-supports', 'bracket-overhang.stl', { supports: true }));
    cases.push(caseOf('cube-scale-333.4', 'cube-40.stl', { scalePercent: 333.4 }));
    cases.push(caseOf('bar230-auto', 'bar-230x20x10.stl'));
    cases.push(caseOf('bar300-p1s-auto', 'bar-300x20x20.stl', {}, { expect: { status: 422, errorCode: 'MODEL_OUT_OF_PRINTER_BOUNDS' } }));
    cases.push(caseOf('bar300-h2d-auto', 'bar-300x20x20.stl', { printerProfile: 'H2D' }));
    cases.push(caseOf('metre-cube-auto', 'cube-0.04-metre-units.stl', {}, { expect: { note: "the service's own answer, equal on A and B" } }));
    cases.push(caseOf('openbox-auto', 'box-open-top-20.stl'));
    cases.push(caseOf('twoshell-auto', 'two-shells-10.stl'));
    cases.push(caseOf('cube3mf-auto', 'cube-40.3mf'));
    cases.push(caseOf('inst8-3mf-auto', 'cube-20-x8-instances.3mf'));
    cases.push(caseOf('bomb3mf-auto', 'expansion-bomb-10x10.3mf', {}, {
        expectDiffers: true,
        timeoutSec: 400,
        expect: { B: { status: 400, errorCode: 'INVALID_SOURCE_GEOMETRY', archive_rule: 'ARCHIVE_EXPANSION_EXCEEDED' } }
    }));
    cases.push(caseOf('step-block-auto', 'block-20x15x10.step'));
    return cases;
}

function main() {
    const outDir = process.argv[2];
    if (!outDir) {
        console.error('usage: node make-corpus.js <output-dir>');
        process.exit(2);
    }
    fs.mkdirSync(outDir, { recursive: true });
    const files = buildFiles();
    const manifest = {};
    for (const [name, data] of Object.entries(files)) {
        fs.writeFileSync(path.join(outDir, name), data);
        manifest[name] = { bytes: data.length, sha256: crypto.createHash('sha256').update(data).digest('hex') };
    }
    const cases = buildCases();
    for (const c of cases) {
        if (!files[c.file]) throw new Error(`case ${c.id} names a missing file ${c.file}`);
        c.sourceSha256 = manifest[c.file].sha256;
    }
    const body = { schema: 'r3d-s390-ab-corpus-v1', generator: 'make-corpus.js', files: manifest, cases };
    fs.writeFileSync(path.join(outDir, 'cases.json'), `${JSON.stringify(body, null, 2)}\n`);
    console.log(`wrote ${Object.keys(files).length} files and ${cases.length} cases to ${outDir}`);
}

if (require.main === module) main();

